LEGACY_RECORDS = [{'source': 'products.csv', 'values': {'archive_audit_note_count': '3', 'archived_attachment_count': '2', 'archive_revision_number': '7', 'reference_document_page_count': '4', 'ProductName': 'Sedans', 'Value': '1200'}}, {'source': 'products.csv', 'values': {'archive_audit_note_count': '4', 'archived_attachment_count': '2', 'archive_revision_number': '6', 'reference_document_page_count': '2', 'ProductName': 'SUVs', 'Value': '1800'}}, {'source': 'products.csv', 'values': {'archive_audit_note_count': '1', 'archived_attachment_count': '1', 'archive_revision_number': '7', 'reference_document_page_count': '8', 'ProductName': 'Electric Vehicles', 'Value': '2500'}}, {'source': 'products.csv', 'values': {'archive_audit_note_count': '1', 'archived_attachment_count': '3', 'archive_revision_number': '2', 'reference_document_page_count': '8', 'ProductName': 'Hybrid Vehicles', 'Value': '2000'}}, {'source': 'products.csv', 'values': {'archive_audit_note_count': '3', 'archived_attachment_count': '3', 'archive_revision_number': '2', 'reference_document_page_count': '4', 'ProductName': 'Trucks', 'Value': '1500'}}, {'source': 'products.csv', 'values': {'archive_audit_note_count': '5', 'archived_attachment_count': '6', 'archive_revision_number': '5', 'reference_document_page_count': '8', 'ProductName': 'Sports Cars', 'Value': '3000'}}, {'source': 'products.csv', 'values': {'archive_audit_note_count': '1', 'archived_attachment_count': '1', 'archive_revision_number': '4', 'reference_document_page_count': '6', 'ProductName': 'Compact Cars', 'Value': '1000'}}, {'source': 'products.csv', 'values': {'archive_audit_note_count': '5', 'archived_attachment_count': '4', 'archive_revision_number': '6', 'reference_document_page_count': '4', 'ProductName': 'Luxury Sedans', 'Value': '3500'}}, {'source': 'products.csv', 'values': {'archive_audit_note_count': '5', 'archived_attachment_count': '1', 'archive_revision_number': '5', 'reference_document_page_count': '6', 'ProductName': 'Vans', 'Value': '1600'}}, {'source': 'products.csv', 'values': {'archive_audit_note_count': '1', 'archived_attachment_count': '2', 'archive_revision_number': '5', 'reference_document_page_count': '8', 'ProductName': 'Pickup Trucks', 'Value': '1700'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team B', 'archive_revision_number': '8', 'archived_attachment_count': '6', 'archive_storage_medium': 'Paper', 'record_index_style': 'Alphabetic', 'reference_document_page_count': '8', 'VehicleID': '1', 'VehicleType': 'Sedans', 'Capacity': '100'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team A', 'archive_revision_number': '7', 'archived_attachment_count': '1', 'archive_storage_medium': 'Hybrid', 'record_index_style': 'Chronological', 'reference_document_page_count': '8', 'VehicleID': '2', 'VehicleType': 'SUVs', 'Capacity': '80'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team A', 'archive_revision_number': '8', 'archived_attachment_count': '1', 'archive_storage_medium': 'Digital', 'record_index_style': 'Chronological', 'reference_document_page_count': '4', 'VehicleID': '3', 'VehicleType': 'Electric Vehicles', 'Capacity': '120'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team A', 'archive_revision_number': '8', 'archived_attachment_count': '6', 'archive_storage_medium': 'Digital', 'record_index_style': 'Numeric', 'reference_document_page_count': '4', 'VehicleID': '4', 'VehicleType': 'Hybrid Vehicles', 'Capacity': '90'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team B', 'archive_revision_number': '6', 'archived_attachment_count': '3', 'archive_storage_medium': 'Digital', 'record_index_style': 'Alphabetic', 'reference_document_page_count': '4', 'VehicleID': '5', 'VehicleType': 'Trucks', 'Capacity': '50'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team C', 'archive_revision_number': '6', 'archived_attachment_count': '3', 'archive_storage_medium': 'Digital', 'record_index_style': 'Chronological', 'reference_document_page_count': '12', 'VehicleID': '6', 'VehicleType': 'Sports Cars', 'Capacity': '30'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team A', 'archive_revision_number': '8', 'archived_attachment_count': '4', 'archive_storage_medium': 'Paper', 'record_index_style': 'Numeric', 'reference_document_page_count': '2', 'VehicleID': '7', 'VehicleType': 'Compact Cars', 'Capacity': '110'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team A', 'archive_revision_number': '2', 'archived_attachment_count': '6', 'archive_storage_medium': 'Paper', 'record_index_style': 'Alphabetic', 'reference_document_page_count': '8', 'VehicleID': '8', 'VehicleType': 'Luxury Sedans', 'Capacity': '40'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team C', 'archive_revision_number': '3', 'archived_attachment_count': '1', 'archive_storage_medium': 'Hybrid', 'record_index_style': 'Numeric', 'reference_document_page_count': '2', 'VehicleID': '9', 'VehicleType': 'Vans', 'Capacity': '60'}}, {'source': 'capacity.csv', 'values': {'record_keeper_group': 'Team B', 'archive_revision_number': '6', 'archived_attachment_count': '1', 'archive_storage_medium': 'Paper', 'record_index_style': 'Numeric', 'reference_document_page_count': '8', 'VehicleID': '10', 'VehicleType': 'Pickup Trucks', 'Capacity': '35'}}]
import gurobipy as gp
from gurobipy import GRB
product_records = [r for r in LEGACY_RECORDS if r['source'] == 'products.csv']
vehicle_types = []
values = {}
for rec in product_records:
    vt = rec['values']['ProductName']
    v = rec['values']['Value']
    vehicle_types.append(vt)
    values[vt] = int(v)
capacity_records = [r for r in LEGACY_RECORDS if r['source'] == 'capacity.csv']
capacities = {}
for rec in capacity_records:
    vt = rec['values']['VehicleType']
    c = rec['values']['Capacity']
    capacities[vt] = int(c)
if set(vehicle_types) != set(capacities.keys()):
    raise ValueError('Mismatch between vehicle types in products.csv and capacity.csv')
total_capacity = sum((capacities[vt] for vt in vehicle_types))
m = gp.Model('Car_Inventory_Optimization')
x = m.addVars(vehicle_types, lb=0, ub=[capacities[vt] for vt in vehicle_types], vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[vt] * x[vt] for vt in vehicle_types)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((x[vt] for vt in vehicle_types)) <= total_capacity, name='total_capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for vt in vehicle_types:
        print(f'x[{vt}]: {x[vt].X}')
else:
    print(f'Solver status: {m.Status}')